1: import isNetworkError from 'is-network-error';
2: 
3: function validateRetries(retries) {
4: 	if (typeof retries === 'number') {
5: 		if (retries < 0) {
6: 			throw new TypeError('Expected `retries` to be a non-negative number.');
7: 		}
8: 
9: 		if (Number.isNaN(retries)) {
10: 			throw new TypeError('Expected `retries` to be a valid number or Infinity, got NaN.');
11: 		}
12: 	} else if (retries !== undefined) {
13: 		throw new TypeError('Expected `retries` to be a number or Infinity.');
14: 	}
15: }
16: 
17: function validateNumberOption(name, value, {min = 0, allowInfinity = false} = {}) {
18: 	if (value === undefined) {
19: 		return;
20: 	}
21: 
22: 	if (typeof value !== 'number' || Number.isNaN(value)) {
23: 		throw new TypeError(`Expected \`${name}\` to be a number${allowInfinity ? ' or Infinity' : ''}.`);
24: 	}
25: 
26: 	if (!allowInfinity && !Number.isFinite(value)) {
27: 		throw new TypeError(`Expected \`${name}\` to be a finite number.`);
28: 	}
29: 
30: 	if (value < min) {
31: 		throw new TypeError(`Expected \`${name}\` to be \u2265 ${min}.`);
32: 	}
33: }
