52: function calculateDelay(retriesConsumed, options) {
53: 	const attempt = Math.max(1, retriesConsumed + 1);
54: 	const random = options.randomize ? (Math.random() + 1) : 1;
55: 
56: 	let timeout = Math.round(random * options.minTimeout * (options.factor ** (attempt - 1)));
57: 	timeout = Math.min(timeout, options.maxTimeout);
58: 
59: 	return timeout;
60: }
61: 
62: function calculateRemainingTime(start, max) {
63: 	if (!Number.isFinite(max)) {
64: 		return max;
65: 	}
66: 
67: 	return max - (performance.now() - start);
68: }
