179: export default async function pRetry(input, options = {}) {
180: 	options = {...options};
181: 
182: 	validateRetries(options.retries);
183: 
184: 	if (Object.hasOwn(options, 'forever')) {
185: 		throw new Error('The `forever` option is no longer supported. For many use-cases, you can set `retries: Infinity` instead.');
186: 	}
187: 
188: 	options.retries ??= 10;
189: 	options.factor ??= 2;
190: 	options.minTimeout ??= 1000;
191: 	options.maxTimeout ??= Number.POSITIVE_INFINITY;
192: 	options.maxRetryTime ??= Number.POSITIVE_INFINITY;
193: 	options.randomize ??= false;
194: 	options.onFailedAttempt ??= () => {};
195: 	options.shouldRetry ??= () => true;
196: 	options.shouldConsumeRetry ??= () => true;
197: 
198: 	// Validate numeric options and normalize edge cases
199: 	validateNumberOption('factor', options.factor, {min: 0, allowInfinity: false});
200: 	validateNumberOption('minTimeout', options.minTimeout, {min: 0, allowInfinity: false});
201: 	validateNumberOption('maxTimeout', options.maxTimeout, {min: 0, allowInfinity: true});
202: 	validateNumberOption('maxRetryTime', options.maxRetryTime, {min: 0, allowInfinity: true});
203: 
204: 	// Treat non-positive factor as 1 to avoid zero backoff or negative behavior
205: 	if (!(options.factor > 0)) {
206: 		options.factor = 1;
207: 	}
208: 
209: 	options.signal?.throwIfAborted();
210: 
211: 	let attemptNumber = 0;
212: 	let retriesConsumed = 0;
213: 	const startTime = performance.now();
214: 
215: 	while (Number.isFinite(options.retries) ? retriesConsumed <= options.retries : true) {
216: 		attemptNumber++;
217: 
218: 		try {
219: 			options.signal?.throwIfAborted();
220: 
221: 			const result = await input(attemptNumber);
222: 
223: 			options.signal?.throwIfAborted();
224: 
225: 			return result;
226: 		} catch (error) {
227: 			if (await onAttemptFailure({
228: 				error,
229: 				attemptNumber,
230: 				retriesConsumed,
231: 				startTime,
232: 				options,
233: 			})) {
234: 				retriesConsumed++;
235: 			}
236: 		}
237: 	}
238: 
239: 	// Should not reach here, but in case it does, throw an error
240: 	throw new Error('Retry attempts exhausted without throwing an error.');
241: }
